/// 拼好的 SVG 串：同一个图标 + 线宽只拼一次（flutter_svg 拿整串当缓存键，每次拼新串、算哈希是白费功夫）
final _svgs = <(DdIcon, double), String>{};

String _svgOf(DdIcon icon, double strokeWidth) => _svgs.putIfAbsent((icon, strokeWidth), () {
  final fill = _fill[icon];
  if (fill != null) return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="${fill.$1}" fill="#000">${fill.$2}</svg>';
  final head = strokeWidth == 1.5 ? _strokeHead : _strokeHead.replaceFirst('stroke-width="1.5"', 'stroke-width="$strokeWidth"');
  return '$head${_stroke[icon]}</svg>';
});

/// [strokeWidth]：描边图标的线宽（Lucide 的 24 格里算），默认 1.5；填色图标不管它
Widget ddIcon(DdIcon icon, {double size = 18, Color color = const Color(0xFF1F2329), double strokeWidth = 1.5}) =>
    SvgPicture.string(_svgOf(icon, strokeWidth), width: size, height: size, colorFilter: ColorFilter.mode(color, BlendMode.srcIn));

/// 「全部设备」的图标（照 UU：2×2 四个实心圆，对角同色、两种蓝）。Phosphor Icons 的 circles-four（fill，@phosphor-icons/core
/// 2.1.1，MIT 许可），原路径按 4 个圆拆开分别上色，形状不变；viewBox 裁到四个圆的范围，和系统小方块一样占满尺寸
const _allDevices = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="40 40 176 176"><path fill="#2f6fea" d="M120,80A40,40,0,1,1,80,40,40,40,0,0,1,120,80Z"/><path fill="#86aef3" d="M176,120a40,40,0,1,0-40-40A40,40,0,0,0,176,120Z"/><path fill="#86aef3" d="M80,136a40,40,0,1,0,40,40A40,40,0,0,0,80,136Z"/><path fill="#2f6fea" d="M176,136a40,40,0,1,0,40,40A40,40,0,0,0,176,136Z"/></svg>';

Widget ddAllDevicesIcon({double size = 20}) => SvgPicture.string(_allDevices, width: size, height: size);

